        $select.multipleSelect("enable");
        // 4. 同步更新隐藏字段
        const hdCoord = document.getElementById(COORDINATOR_HIDDEN_ID);
        if (hdCoord) {
            hdCoord.value = coordinatorIds.join(",");
        }
        console.log("[Prebilling] Coordinator selected and enabled:", coordinatorIds);
