function getAideName(ctx = document) {
    let aideName, flag = false;
    // 2 Windows: 0-topWindow, 1-popupWindow
    let topWidow = window.parent;
    // 0. Direct read from popup hidden field (NonskilledVisitInfo_ns popup, Call/Patient page)
    const hdnCGName = ctx.querySelector("#hdnCaregiverName")
        ?.value;
    if (hdnCGName)
        return hdnCGName;
    // 1. On patient page
    if (!flag) {
        let aideLinks = topWidow[0]?.document?.querySelectorAll("#aidelink") ?? [];
        for (const aideLink of aideLinks) {
            if (aideLink
                .getAttribute("onClick")
                ?.includes($(visitDateSelector, ctx).text())) {
                aideName = aideLink.innerHTML.trim();
                flag = true;
                break;
            }
        }
    }
    // 2. On caregiver page
    if (!flag) {
        let result = MissedCall_searchElementInAllFrames(window.top, caregiverInfoNameSelector);
        if (result != null) {
            aideName = result.innerText.trim();
            flag = true;
        }
    }
    // 3. On CHHA Patient page
    if (!flag) {
        let hhaxLinks = topWidow[0]?.document?.querySelectorAll(".hhax-link") ?? [];
        for (const hhaxLink of hhaxLinks) {
            if (hhaxLink
                .getAttribute("onClick")
                ?.includes($(visitDateSelector, ctx).text())) {
                const aideProfileLink = $(hhaxLink)
                    .parent()
                    .find("a[onclick^='OpenAideProfileMax']")[0];
                if (aideProfileLink) {
                    aideName = aideProfileLink.innerText.trim();
                    flag = true;
                    break;
                }
            }
        }
    }
    // 4. On CHHA Prebilling page
    if (!flag) {
        let table = MissedCall_searchElementInAllFrames(window.top, prebillingSearchResultsSelector);
        if (table) {
            let list = table.querySelectorAll("tbody > tr");
            for (const visit of list) {
                let date = visit.querySelector("td:nth-child(1)");
                let id = visit.querySelector("td:nth-child(2) > a");
                let time = visit.querySelector("td:nth-child(9)");
                if (date?.innerText ==
                    $(prebillingVisitDateSelector, ctx).text() &&
                    id.innerText ==
                        $(prebillingVisitAdmissionIdSelector, ctx).text() &&
                    time.innerText ==
                        $(prebillingVisitScheduledTimeSelector, ctx).text()) {
                    aideName = visit.querySelector("td:nth-child(6) > a").innerText
                        .split("\n")[0]
                        .trim();
                    flag = true;
                    break;
                }
            }
        }
    }
    if (!flag) {
        aideName = "AideNotFound";
        alert("AideNotFound");
    }
    return aideName;
}
function MissedCall_searchElementInAllFrames(win, selector) {
    let result = null;
    function searchWindow(currentWindow) {
        try {
            if (currentWindow.document) {
                const foundElement = currentWindow.document.querySelector(selector);
                if (foundElement) {
                    result = foundElement;
                    return true; // 找到了，停止搜索
                }
            }
        }
        catch (e) {
            console.warn("无法访问的 window:", e);
        }
        try {
            for (let i = 0; i < currentWindow.frames.length; i++) {
                const frame = currentWindow.frames[i];
                if (searchWindow(frame)) {
                    return true; // 子frame中找到了，停止搜索
                }
            }
        }
        catch (e) {
            console.warn("无法访问 frames:", e);
        }
        return false; // 当前window和子frames都没找到
    }
    searchWindow(win);
    return result;
}
function missedCallTimeInputer(reason, ctx = document) {
    if (reason == "Attendant failed to call in") {
        $(visitStartTimeInputSelector, ctx).val($(visitScheduleTimeSelector, ctx).text().split("-")[0]);
        $(visitStartTimeInputSelector, ctx)[0].dispatchEvent(new Event("change"));
    }
    else if (reason == "Attendant failed to call out") {
        $(visitEndTimeInputSelector, ctx).val($(visitScheduleTimeSelector, ctx).text().split("-")[1]);
        $(visitEndTimeInputSelector, ctx)[0].dispatchEvent(new Event("change"));
    }
    else if (reason == "Attendant failed to call in and out") {
        $(visitStartTimeInputSelector, ctx).val($(visitScheduleTimeSelector, ctx).text().split("-")[0]);
        $(visitStartTimeInputSelector, ctx)[0].dispatchEvent(new Event("change"));
        $(visitEndTimeInputSelector, ctx).val($(visitScheduleTimeSelector, ctx).text().split("-")[1]);
        $(visitEndTimeInputSelector, ctx)[0].dispatchEvent(new Event("change"));
    }
    else {
        console.log("Something went error");
    }
}
async function missedCalledReasonChooser(reason, ctx = document) {
    let expectedReason = reason, expectedAction = "Confirmed visit with the client or the client's family member/representative and documented";
    let select1 = $(visitReasonSelector, ctx);
    for (const reason of $(visitReasonOptionSelector, ctx)) {
        if (expectedReason == reason.innerText) {
            select1.val(reason.value);
            select1[0].dispatchEvent(new Event("change"));
            break;
        }
    }
    await sleep(500);
    let select2 = $(visitActionSelector, ctx);
    for (const action of $(visitActionOptionSelector, ctx)) {
        if (expectedAction == action.innerText) {
            select2.val(action.value);
            select2[0].dispatchEvent(new Event("change"));
            break;
        }
    }
}
function getScheduleTime(ctx = document) {
    return {
        startTime: convertMilitaryTime($(visitScheduleTimeSelector, ctx).text().split("-")[0]),
        endTime: convertMilitaryTime($(visitScheduleTimeSelector, ctx).text().split("-")[1]),
    };
}

;// ./src/js/services/HhaSearchService.ts

const FALLBACK_TENANT_BASE_URL = "https://app.hhaexchange.com/ENT2603010000";
let hasWarnedTenantFallback = false;
// ==================== 动态 Tenant URL 检测 ====================
/**
 * 动态检测当前 HHAExchange 租户路径前缀
 * 支持所有已知 URL 格式：ENT / HHANotification / ENTP
 * 并在同源 iframe 中尝试从父窗口推导，避免版本升级触发强制登出
 */
function detectTenantBaseUrl() {
    const host = window.location.hostname.toLowerCase();
    const isHhaHost = host.endsWith("hhaexchange.com");
    function extractVersion(url) {
        const m1 = url.match(/\/ENT(\d+)\//);
        if (m1)
            return m1[1];
        const m2 = url.match(/\/(?:HHANotification|ENTP)(\d+)\//);
        if (m2)
            return m2[1];
        return null;
    }
    const r1 = extractVersion(window.location.pathname);
    if (r1)
        return `https://app.hhaexchange.com/ENT${r1}`;
    for (const script of Array.from(document.scripts)) {
        if (script.src) {
            const r2 = extractVersion(script.src);
            if (r2)
                return `https://app.hhaexchange.com/ENT${r2}`;
        }
    }
    const r3 = extractVersion(window.location.href);
    if (r3)
        return `https://app.hhaexchange.com/ENT${r3}`;
    try {
        if (window.parent !== window) {
            const r4 = extractVersion(window.parent.location.href);
            if (r4)
                return `https://app.hhaexchange.com/ENT${r4}`;
        }
    }
    catch (_) {
        /* 跨域父窗口，跳过 */
    }
    if (isHhaHost && !hasWarnedTenantFallback) {
        hasWarnedTenantFallback = true;
        console.warn("[HhaSearchService] Could not detect tenant prefix from URL, using fallback");
    }
    return FALLBACK_TENANT_BASE_URL;
}
// ==================== URL 常量 ====================
const _TENANT_BASE_URL = detectTenantBaseUrl();
/** Aide (护工) 搜索 URL - 使用动态租户前缀 */
const AIDE_SEARCH_URL = `${_TENANT_BASE_URL}/Aide/AideSearchXSLT_ns.aspx?FirstName=&Phone=`;
const AIDE_SEARCH_PARAMS = "&LastName=&Type=-1&Discipline=-1&CaregiverCode=&ALtCaregiverCode=&Status=-1&SSN=&CaregiverTeamID=-1&FromVisitEdit=0&CaregiverLocationID=-1&CaregiverBranchID=-1&VisitDate=&office=469,5137,5139,6475,14849&DOB=&pg=1&sort=&ord=ASC&FromPage=";
const AIDE_PROFILE_URL_TEMPLATE = `${_TENANT_BASE_URL}/Aide/Aide_ns.aspx?AideId={ID}`;
