        const cleanedNumber = normalizePhoneNumber(phoneNumber);
        // 验证号码长度（必须是 10 位）
        if (cleanedNumber.length !== 10) {
            console.log("[Highlight2Call] 号码长度不正确，跳过弹窗:", phoneNumber, "->", cleanedNumber);
            return;
        }
