        popup.style.top = `${top}px`;
        popup.style.left = `${left}px`;
        // --- 事件绑定 ---
        // 使用 <HTMLDivElement> 类型断言，确保 querySelector 返回正确的类型
        const closeButton = popup.querySelector(".hcp-close-btn");
