            if (!this.controllerInjected) {
                await this.injectDOMController();
            }
            // 等待 Controller 就绪
            // 注意：使用 unsafeWindow 访问页面主世界中的 Controller
            if (!unsafeWindow.HHAOutlookController) {
                await this.waitForController();
            }
